{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://kubaik.github.io/jwt-sessions-revocation-rotation-storage/#faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I revoke a JWT immediately?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You cannot revoke a JWT in a purely stateless system. To achieve immediate revocation, you must introduce state: either a blocklist of revoked jti values checked on every request, or a session store that tracks valid tokens. The practical approach is to use short-lived access tokens (e.g., 5–15 minutes) and revoke the refresh token, accepting a small window of validity for the access token. For immediate revocation, combine a blocklist with a short TTL."
      }
    },
    {
      "@type": "Question",
      "name": "Should I store JWT in localStorage or cookies?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It depends on your threat model. localStorage is vulnerable to XSS but immune to CSRF. HttpOnly cookies are immune to XSS token theft but require CSRF protection. For most SPAs, storing the access token in memory and the refresh token in an HttpOnly, Secure, SameSite cookie is a balanced approach. Avoid localStorage for long-lived tokens if you have any third-party scripts."
      }
    },
    {
      "@type": "Question",
      "name": "What happens if a refresh token is stolen?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "With rotation and reuse detection, a stolen refresh token can be used once. When the legitimate client attempts to use the old token, the server detects reuse and revokes the entire token family, forcing re-authentication. This limits the attacker's window. Without rotation, a stolen refresh token grants persistent access until expiry."
      }
    },
    {
      "@type": "Question",
      "name": "How often should I rotate signing keys?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "There is no universal answer. A common practice is to rotate signing keys periodically (e.g., every 90 days) and maintain an overlap period where both old and new keys are published in the JWKS endpoint. The overlap should be at least as long as the maximum access token lifetime to avoid invalidating active tokens. Automate the rotation and ensure your verifiers refresh their key cache regularly."
      }
    }
  ]
}
